BEGIN TRANSACTION;
CREATE TABLE dostawcy (dostawca_id INTEGER PRIMARY KEY, nazwa TEXT NOT NULL, kraj TEXT NOT NULL, nip TEXT UNIQUE, email TEXT, ocena REAL CHECK(ocena BETWEEN 1 AND 5));
CREATE TABLE kategorie (kategoria_id INTEGER PRIMARY KEY, nazwa TEXT NOT NULL UNIQUE, opis TEXT, stawka_vat REAL NOT NULL CHECK(stawka_vat IN (0, 0.05, 0.08, 0.23)));
CREATE TABLE klienci (klient_id INTEGER PRIMARY KEY, typ_klienta TEXT NOT NULL CHECK(typ_klienta IN ('B2C','B2B')), imie TEXT, nazwisko TEXT, nazwa_firmy TEXT, email TEXT NOT NULL UNIQUE, miasto TEXT NOT NULL, wojewodztwo TEXT NOT NULL, kod_pocztowy TEXT, data_rejestracji DATE NOT NULL, segment TEXT NOT NULL CHECK(segment IN ('Standard','Premium','VIP')));
CREATE TABLE platnosci (platnosc_id INTEGER PRIMARY KEY, zamowienie_id INTEGER NOT NULL UNIQUE REFERENCES zamowienia ON DELETE CASCADE, data_platnosci DATE, kwota_brutto REAL NOT NULL CHECK(kwota_brutto >= 0), metoda TEXT NOT NULL CHECK(metoda IN ('Karta','BLIK','Przelew','Pobranie','PayPal')), status TEXT NOT NULL CHECK(status IN ('Oplacona','Oczekujaca','Zwrocona')));
CREATE TABLE pozycje_zamowien (pozycja_id INTEGER PRIMARY KEY, zamowienie_id INTEGER NOT NULL REFERENCES zamowienia ON DELETE CASCADE, produkt_id INTEGER NOT NULL REFERENCES produkty, ilosc INTEGER NOT NULL CHECK(ilosc > 0), cena_jednostkowa_netto REAL NOT NULL CHECK(cena_jednostkowa_netto >= 0), rabat_proc REAL NOT NULL DEFAULT 0 CHECK(rabat_proc BETWEEN 0 AND 100));
CREATE TABLE produkty (produkt_id INTEGER PRIMARY KEY, ean TEXT NOT NULL UNIQUE, sku TEXT NOT NULL UNIQUE, nazwa TEXT NOT NULL, opis TEXT, marka TEXT NOT NULL, kategoria_id INTEGER NOT NULL REFERENCES kategorie, dostawca_id INTEGER REFERENCES dostawcy, cena_zakupu_netto REAL NOT NULL CHECK(cena_zakupu_netto >= 0), cena_sprzedazy_netto REAL NOT NULL CHECK(cena_sprzedazy_netto >= 0), jednostka TEXT NOT NULL, waga_kg REAL, kolor TEXT, rozmiar TEXT, material TEXT, data_wprowadzenia DATE, aktywny INTEGER NOT NULL DEFAULT 1 CHECK(aktywny IN (0,1)));
CREATE TABLE stany_magazynowe (stan_id INTEGER PRIMARY KEY, produkt_id INTEGER NOT NULL REFERENCES produkty, magazyn TEXT NOT NULL, ilosc_dostepna INTEGER NOT NULL CHECK(ilosc_dostepna >= 0), prog_zamowienia INTEGER NOT NULL, data_aktualizacji DATE NOT NULL, UNIQUE(produkt_id, magazyn));
CREATE TABLE zamowienia (zamowienie_id INTEGER PRIMARY KEY, numer_zamowienia TEXT NOT NULL UNIQUE, klient_id INTEGER NOT NULL REFERENCES klienci, data_zamowienia DATE NOT NULL, kanal TEXT NOT NULL CHECK(kanal IN ('Sklep online','Marketplace','Sklep stacjonarny','Telefon')), status TEXT NOT NULL CHECK(status IN ('Zrealizowane','Wyslane','Anulowane','Zwrocone')), metoda_dostawy TEXT NOT NULL, koszt_dostawy_netto REAL NOT NULL DEFAULT 0, rabat_netto REAL NOT NULL DEFAULT 0);
CREATE INDEX idx_zamowienia_data ON zamowienia(data_zamowienia);
CREATE INDEX idx_pozycje_produkt ON pozycje_zamowien(produkt_id);
CREATE INDEX idx_produkty_kategoria ON produkty(kategoria_id);
CREATE INDEX idx_klienci_miasto ON klienci(miasto);
CREATE VIEW v_sprzedaz_szczegoly AS SELECT z.zamowienie_id, z.numer_zamowienia, z.data_zamowienia, z.kanal, z.status, k.klient_id, COALESCE(k.nazwa_firmy, k.imie || ' ' || k.nazwisko) AS klient, k.typ_klienta, p.produkt_id, p.ean, p.sku, p.nazwa AS produkt, kat.nazwa AS kategoria, p.marka, p.cena_zakupu_netto, p.cena_sprzedazy_netto, pz.ilosc, pz.cena_jednostkowa_netto, pz.rabat_proc, ROUND(pz.ilosc * pz.cena_jednostkowa_netto * (1-pz.rabat_proc/100.0),2) AS wartosc_netto, ROUND(pz.ilosc * pz.cena_jednostkowa_netto * (1-pz.rabat_proc/100.0) * (1+kat.stawka_vat),2) AS wartosc_brutto FROM zamowienia z JOIN klienci k ON k.klient_id=z.klient_id JOIN pozycje_zamowien pz ON pz.zamowienie_id=z.zamowienie_id JOIN produkty p ON p.produkt_id=pz.produkt_id JOIN kategorie kat ON kat.kategoria_id=p.kategoria_id;
COMMIT;
